import os
import json
from google.cloud import documentai_v1 as documentai

def extract_tables(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = config.get("location") or os.environ.get("DOCUMENTAI_LOCATION", "us")
    processor_id = config.get("processor_id") or os.environ.get("DOCUMENTAI_PROCESSOR_ID")
    mime_type = config.get("mime_type") or "application/pdf"

    if not project_id or not processor_id:
        raise ValueError("project_id and processor_id are required (via config or environment variables).")

    client = documentai.DocumentProcessorServiceClient()
    processor_name = client.processor_path(project_id, location, processor_id)

    if isinstance(payload, dict) and "content" in payload:
        content = payload["content"]
        if isinstance(content, str):
            document_content = content.encode("utf-8")
        else:
            document_content = content
    elif isinstance(payload, (bytes, bytearray)):
        document_content = bytes(payload)
    elif isinstance(payload, str):
        with open(payload, "rb") as f:
            document_content = f.read()
        mime_type = mime_type or "application/pdf"
    else:
        raise TypeError("payload must be bytes, bytearray, str path, or dict with content")

    raw_document = documentai.RawDocument(content=document_content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
    response = client.process_document(request=request)
    doc = response.document

    result = []
    for page_index, page in enumerate(doc.pages):
        page_result = {"page_number": page_index + 1, "tables": []}
        for table in page.tables:
            table_result = {"header_rows": [], "body_rows": []}

            for row in table.header_rows:
                row_cells = []
                for cell in row.cells:
                    row_cells.append(
                        {
                            "text": documentai.Document.TextAnchor.get_text(
                                doc.text, cell.layout.text_anchor
                            ).strip()
                            if cell.layout.text_anchor and cell.layout.text_anchor.text_segments
                            else "",
                            "row_span": cell.row_span,
                            "col_span": cell.col_span,
                        }
                    )
                table_result["header_rows"].append(row_cells)

            for row in table.body_rows:
                row_cells = []
                for cell in row.cells:
                    row_cells.append(
                        {
                            "text": documentai.Document.TextAnchor.get_text(
                                doc.text, cell.layout.text_anchor
                            ).strip()
                            if cell.layout.text_anchor and cell.layout.text_anchor.text_segments
                            else "",
                            "row_span": cell.row_span,
                            "col_span": cell.col_span,
                        }
                    )
                table_result["body_rows"].append(row_cells)

            page_result["tables"].append(table_result)
        result.append(page_result)

    return result
